<template><section class="integration-cohort"><h3>Named species comparison</h3><p>The same selected cohort supplies the fingerprint, PCA, distances and variability. Descriptors use each species' complete original Core population.</p><div class="integration-toolbar"><label>Registered species search <input v-model="search" placeholder="Species name or registry ID" /></label><button class="btn subtle" @click="find">Find species</button></div><div class="integration-scroll"><ul><li v-for="r in results" :key="r.species_id"><button class="ghost-link" @click="add(r.species_id)">Add {{ r.display_name||r.species_id }}</button></li></ul></div><div class="integration-toolbar"><span v-for="sid in selected" :key="sid" class="integration-chip">{{ sid }} <button :aria-label="'Remove '+sid" @click="selected=selected.filter(s=>s!==sid)">×</button></span></div><button class="btn subtle" :disabled="selected.length<2||selected.length>32" @click="context.selectCohort(selected)">Compute selected {{ selected.length }} species</button><p v-if="context.cohortTask.value" role="status">Cohort {{ context.cohortTask.value.status }} · {{ Math.round((context.cohortTask.value.progress||0)*100) }}% · The complete selected Core population is being processed.</p><p v-if="context.error.value" role="alert">{{ context.error.value }}</p><p v-if="error" role="alert">{{ error }}</p><p v-if="context.cohort.value">rank={{ context.cohort.value.rank }} · excluded={{ context.cohort.value.excluded_species.length }} · cohort {{ context.cohort.value.cohort_key }}</p><ul v-if="context.cohort.value?.excluded_species.length"><li v-for="r in context.cohort.value.excluded_species" :key="r.species_id">{{ r.species_id }}: {{ r.reason }}</li></ul></section></template>
<script setup>
import {ref,watch} from 'vue';import client from '../../api/client'
const props=defineProps({context:Object});const selected=ref([]),search=ref(''),results=ref([]),error=ref('')
watch(()=>props.context.cohort.value,r=>{if(r)selected.value=[...r.species_ids]},{immediate:true})
async function find(){try{const r=await client.get('/stoichdb/species/',{params:{query:search.value,page_size:20,include_aggregate:'false'}});const data=r.data.data;results.value=data.items||data.results||data.species||[];error.value=''}catch(e){error.value=e.message}}
function add(id){if(!selected.value.includes(id)&&selected.value.length<32)selected.value.push(id)}
</script>
